(function(){
 'use strict';
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const txt=(x,y,s,size=20)=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="${size}" fill="#111">${esc(s)}</text>`;
 const ln=(a,b,extra='')=>`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#111" ${extra.includes('stroke-width=')?'':'stroke-width="2"'} ${extra}/>`;
 const path=(d,extra='')=>`<path d="${d}" fill="none" stroke="#111" stroke-width="2" ${extra}/>`;
 const rect=(x,y,w,h)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="white" stroke="#111" stroke-width="2"/>`;
 const poly=ps=>path('M'+ps.join('L')+'Z');
 const arrow=(a,b)=>{const t=Math.atan2(b[1]-a[1],b[0]-a[0]);return ln(a,b)+path(`M${b[0]-10*Math.cos(t-.4)},${b[1]-10*Math.sin(t-.4)}L${b}L${b[0]-10*Math.cos(t+.4)},${b[1]-10*Math.sin(t+.4)}`);};
 const rad=a=>a*Math.PI/180,point=(p,a,r)=>[p[0]+r*Math.cos(rad(a)),p[1]-r*Math.sin(rad(a))];
 function cross(a,b,c,d){const u=b.map((n,i)=>n-a[i]),v=d.map((n,i)=>n-c[i]),w=c.map((n,i)=>n-a[i]),t=(w[0]*v[1]-w[1]*v[0])/(u[0]*v[1]-u[1]*v[0]);return a.map((n,i)=>n+t*u[i]);}
 function right(p,a,b,r=14){const unit=q=>q.map((n,i)=>(n-p[i])/Math.hypot(q[0]-p[0],q[1]-p[1])),u=unit(a),v=unit(b),q=(x,y)=>p.map((n,i)=>n+r*(x*u[i]+y*v[i]));return path(`M${q(1,0)}L${q(1,1)}L${q(0,1)}`);}
 function arc(p,a,b,label,r=28){let x=Math.atan2(a[1]-p[1],a[0]-p[0]),d=Math.atan2(b[1]-p[1],b[0]-p[0])-x;while(d>Math.PI)d-=2*Math.PI;while(d< -Math.PI)d+=2*Math.PI;const q=(t,k)=>[p[0]+k*Math.cos(t),p[1]+k*Math.sin(t)];return path(`M${q(x,r)}A${r} ${r} 0 0 ${d>0?1:0} ${q(x+d,r)}`)+txt(...q(x+d/2,r+27).map((n,i)=>n+(i?6:0)),label,18);}
 function quad(){const A=[80,350],B=[560,350],C=cross(A,point(A,35,100),B,point(B,110,100)),D=cross(A,point(A,80,100),C,[C[0]-100,C[1]]);return {points:{A,B,C,D},box:'0 0 650 430',body:poly([A,B,C,D])+ln(A,C)+arc(A,B,C,'35°',48)+arc(A,C,D,'45°',28)+arc(B,A,C,'70°',35)+arc(C,B,D,'110°',42)+arc(D,A,C,'x°',28)+[A,B,C,D].map((p,i)=>txt(p[0]+(i===3?-18:0),p[1]+(i<2?29:-15),'ABCD'[i])).join(''),alt:'四邊形ABCD加對角線AC；A角分成35與45度，B為70度，C的整角110度，D未知。'};}
 function opposite(){const center=[325,210],B=point(center,180,180),D=point(center,0,180),A=point(center,100,180),C=point(center,320,180);return {points:{A,B,C,D},box:'0 0 650 440',body:poly([A,B,C,D])+right(A,B,D)+right(C,B,D)+arc(B,A,C,'較小角',40)+arc(D,A,C,'較大角',40)+txt(325,408,'兩個未標直角的角相差 40°',21),alt:'四邊形的兩個對角有直角記號，另兩個角以較小角和較大角標示，相差40度。'};}
 function iso(){const A=[325,70],B=[325-270*Math.tan(rad(25)),340],C=[325+270*Math.tan(rad(25)),340];const tick=(a,b)=>{const m=a.map((n,i)=>(n+b[i])/2);return ln([m[0]-7,m[1]-3],[m[0]+7,m[1]+3]);};return {points:{A,B,C},box:'0 0 650 420',body:poly([A,B,C])+tick(A,B)+tick(A,C)+arc(A,B,C,'x°',35)+arc(B,A,C,'x＋15°',27)+arc(C,A,B,'x＋15°',27)+txt(325,398,'斜邊上的同樣短記號表示兩邊等長',18),alt:'等腰三角形，頂角x，兩底角各x加15度；兩腰有等長記號。'};}
 function chart(v){const L=70,R=595,T=45,B=285,max=Math.ceil((Math.max(...v.values)+1)/v.step)*v.step;let body='';for(let n=0;n<=max;n+=v.step){const y=B-(B-T)*n/max;body+=ln([L,y],[R,y],'stroke-width=".7"')+txt(L-25,y+6,n,17);}body+=arrow([L,B],[R+15,B])+arrow([L,B],[L,T-18])+txt(42,24,v.unit,18);const points=v.values.map((n,i)=>[L+i*(R-L)/(v.values.length-1),B-n/max*(B-T)]);body+=path('M'+points.join('L'));points.forEach((p,i)=>{body+=`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="white" stroke="#111"/>`+txt(p[0],B+32,v.labels[i],18);});return {box:'0 0 650 350',body,alt:v.labels.map((s,i)=>s+' '+v.values[i]+v.unit).join('；')};}
 function angles(kind){let body='';
  if(kind==='bAngleCompare'){const a=[110,265],b=[435,265],a1=[110,130],a2=[245,265],b1=[285,115],b2=[585,115];body=path(`M${a1}L${a}L${a2}M${b1}L${b}L${b2}`)+right(a,a1,a2)+right(b,b1,b2)+txt(170,318,'甲')+txt(435,318,'乙');}
  if(kind==='bSplitRight'){const p=[160,300],a=[160,65],b=[550,300],c=[335,125];body=path(`M${a}L${p}L${b}M${p}L${c}`)+right(p,a,b,20)+arc(p,a,c,'甲',55)+arc(p,c,b,'乙',55);}
  if(kind==='bThreeAngles'){[90,45,135].forEach((deg,i)=>{const p=[95+i*215,235],a=point(p,deg,105),b=point(p,0,105);body+=path(`M${a}L${p}L${b}`)+arc(p,a,b,['甲','乙','丙'][i],25);});}
  if(kind==='bAngleMeasure'){const p=[200,285],a=[270,75],b=[540,285],u=point(p,20,215),v=point(p,110,150);body=path(`M${a}L${p}L${b}`)+path(`M${p}L${u}L${v}Z`,'stroke-dasharray="6 5"')+right(p,u,v,20)+txt(360,345,'頂點相同，但三角尺的邊尚未對齊',18);}
  if(kind==='bRoute'){const ps=[[60,75],[260,75],[260,180],[450,180],[450,295],[590,295]];body=path('M'+ps.join('L'))+txt(62,46,'起點')+txt(590,329,'終點');}
  return {box:'0 0 650 365',body,alt:kind==='bRoute'?'由起點依序向右、向下、向右、向下、向右到終點；依路段交接位置判讀轉彎。':kind==='bAngleMeasure'?'實線是待比較的角，虛線三角尺只有頂點對齊，一邊尚未與原角重合。':kind==='bThreeAngles'?'甲直角、乙張開較小、丙張開較大。':kind==='bSplitRight'?'一個直角被中間射線分成兩個較小的角。':'甲乙都有直角記號，乙的兩邊較長且朝向不同。'};
 }
 function solids(v){let body='';const edge=(ps,edges)=>edges.map(([a,b,d])=>ln(ps[a],ps[b],d?'stroke-dasharray="6 5"':'')).join('');
  const prism=v.mode==='quad'?[[65,120],[195,120],[195,255],[65,255],[110,65],[240,65],[240,200],[110,200]]:[[60,150],[145,70],[230,150],[60,310],[145,230],[230,310]];
  body+=edge(prism,v.mode==='quad'?[[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7,1],[7,4,1],[0,4],[1,5],[2,6],[3,7,1]]:[[0,1],[1,2],[2,0],[3,4,1],[4,5,1],[5,3],[0,3],[1,4,1],[2,5]]);
  const pyramid=v.mode?[[420,235],[555,235],[590,175],[455,175],[505,55]]:[[420,245],[590,245],[520,160],[505,55]];
  body+=edge(pyramid,v.mode?[[0,1],[1,2],[2,3,1],[3,0,1],[0,4],[1,4],[2,4],[3,4,1]]:[[0,1],[1,2,1],[2,0,1],[0,3],[1,3],[2,3,1]]);
  body+=txt(155,330,v.mode==='quad'?'甲：四角柱':'甲：三角柱')+txt(505,330,v.mode?'乙：四角錐':'乙：三角錐')+txt(325,376,'互不共用邊、面或頂點；虛線表示被遮住的邊',17);
  return {box:'0 0 650 405',body,alt:(v.mode==='quad'?'四角柱': '三角柱')+'及'+(v.mode?'四角錐':'三角錐')+'的骨架，虛線也是實際存在的邊。'};
 }
 function shadow(v){let body='';v.table.rows.forEach((r,i)=>{const h=Number(r[2])*5,d=30*130/(h-30),y=75+i*160,L=[320-d,y],top=[320,y-15],bot=[320,y+15],a=[450,y-h/2],b=[450,y+h/2];body+=txt(30,y-25,r[0],23)+`<circle cx="${L[0]}" cy="${L[1]}" r="7" fill="white" stroke="#111"/>`+path(`M${L}L${a}M${L}L${b}`)+ln(top,bot,'stroke-width="7"')+ln([450,y-65],[450,y+65])+ln(a,b,'stroke-width="7"')+txt(L[0],y+43,'光源',16)+txt(325,y+48,'模型',16)+txt(490,y+10,r[2]+' cm',19);});return {box:'0 0 650 535',body:body+txt(325,524,'模型和屏幕固定，只移動光源；光線以直線表示',18),alt:'甲乙丙使用相同模型與屏幕位置，光源由遠到近，影子高度依序9、15、22公分。'};}
 function mirror(){let body='';for(let i=0;i<3;i++){const x=i*220;body+=`<g transform="translate(${x} 0)">${txt(110,30,['甲 原方向','乙 轉鏡面','丙 遮光路'][i],20)}${ln([20,65],[218,65])}${txt(120,53,'牆面',16)}${ln(i===1?[110,203]:[120,210],i===1?[190,157]:[180,150],'stroke-width="5"')}${arrow([30,180],i===2?[80,180]:[150,180])}${i===2?ln([88,148],[88,211],'stroke-width="6"'):arrow([150,180],i===1?[216,65]:[150,65])}${txt(90,246,'光源 → 鏡面',17)}</g>`;}return {box:'0 0 670 290',body,alt:'甲光照到鏡面再反射至牆；乙轉鏡面後反射位置改變；丙紙板擋住光路。各圖是配置示意。'};}
 function community(){const sites=[[125,95,'圖書館'],[515,95,'活動中心'],[125,325,'學校'],[515,325,'公園']];return {box:'0 0 650 430',body:poly([[125,95],[515,95],[515,325],[125,325]])+sites.map(([x,y,s])=>rect(x-65,y-25,130,50)+txt(x,y+7,s,21)).join('')+path('M260 80l20 30m0-30l20 30m0-30l20 30m0-30l20 30')+txt(320,55,'北側直通路施工')+arrow([590,240],[590,160])+txt(590,145,'N')+txt(325,402,'外圍道路可通行；方位示意，不提供實際距離',18),alt:'圖書館西北、活動中心東北、學校西南、公園東南；圖書館至活動中心北側道路施工，其餘外圍可通行。'};}
 function river(){return {box:'0 0 650 490',body:path('M90 55Q125 145 225 170T350 300T535 425')+path('M105 50Q140 130 240 155T365 285T550 415')+arrow([170,146],[210,165])+arrow([300,218],[330,267])+arrow([430,345],[480,389])+txt(82,34,'甲：上游')+txt(360,235,'乙：中游')+txt(540,450,'丙：下游、出海處')+rect(226,134,27,27)+txt(315,147,'取水設施')+poly([[35,105],[67,47],[100,105]])+txt(285,82,'由高處流向低處')+txt(325,480,'流向示意；未提供距離、流速或水質資料',17),alt:'河水依甲上游、乙中游、丙下游流向出海處；取水設施在甲乙之間，圖無流速或水質資料。'};}
 function cup(){let body='<defs><pattern id="b-water" width="18" height="18" patternUnits="userSpaceOnUse"><path d="M0 9H18" stroke="#aaa" stroke-width=".7"/></pattern></defs>';
  for(let i=0;i<2;i++){body+=`<g transform="translate(${i*330} 0)">${txt(155,30,i?'乙 傾斜讓氣泡逸出':'甲 垂直壓入',21)}${rect(20,60,275,260)}<rect x="21" y="76" width="273" height="243" fill="url(#b-water)"/>${ln([20,76],[295,76])}<g transform="rotate(${i?25:0} 145 190)"><path d="M85 260V110H205V260" fill="${i?'none':'white'}" stroke="#111" stroke-width="3"/>${rect(118,125,55,14)}</g>${i?[230,245,260].map((x,j)=>`<circle cx="${x}" cy="${240-j*45}" r="${7-j}" fill="white" stroke="#111"/>`).join(''):txt(145,193,'杯內空氣',18)}${txt(155,363,i?'氣泡上升，水較能進入':'紙巾固定在杯底',19)}</g>`;}
  return {box:'0 0 660 400',body,alt:'杯口向下且整杯壓入水中，甲保持垂直、杯內空氣使紙巾未濕；乙傾斜使氣泡逸出，水進入。圖示不量化水位。'};
 }
 function pistons(){let body='';for(let i=0;i<3;i++){const y=40+i*145;body+=`<g transform="translate(0 ${y})">${txt(325,18,['甲 空氣：密合','乙 水：密合','丙 接頭鬆開'][i],21)}${rect(80,48,160,50)}${rect(420,48,160,50)}${ln([110,43],[110,103],'stroke-width="5"')}${ln([20,73],[110,73],'stroke-width="4"')}${ln([20,53],[20,93],'stroke-width="4"')}${ln([490,43],[490,103],'stroke-width="5"')}${ln([490,73],[635,73],'stroke-width="4"')}${ln([635,53],[635,93],'stroke-width="4"')}${path(i===2?'M240 73H305M320 73H420':'M240 73H420')}${arrow([35,115],[78,115])}${i===2?txt(320,122,'此處未密合',18):arrow([595,115],[640,115])}${i===1?[60,76,91].map(y=>ln([115,y],[235,y],'stroke-width=".7"')+ln([425,y],[485,y],'stroke-width=".7"')).join(''):''}</g>`;}return {box:'0 0 680 480',body,alt:'相對的兩支注射筒以管子連接；甲裝空氣、乙裝水均密合，丙管路接頭鬆開。推左端時觀察右端，圖未給移動距離。'};}
 function draw(v){if(!v.kind?.startsWith('b'))return null;if(v.kind==='bLineChart')return chart(v);if(v.kind==='bQuadSplit')return quad();if(v.kind==='bOppositeRight')return opposite();if(v.kind==='bIsosceles')return iso();if(['bAngleCompare','bRoute','bSplitRight','bThreeAngles','bAngleMeasure'].includes(v.kind))return angles(v.kind);if(v.kind==='bSolidCompare')return solids(v);if(v.kind==='bShadow')return shadow(v);if(v.kind==='bMirror')return mirror();if(v.kind==='bCommunity')return community();if(v.kind==='bRiver')return river();if(v.kind==='bCupAir')return cup();if(v.kind==='bPistons')return pistons();return null;}
 window.BExamDiagrams={draw,quad,opposite,iso};
})();
